import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator, delegatingTo, stopOwnedEngines} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.

interface Frame {
  type: string;
  sessionId?: string;
  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
  code?: string;
  message?: string;
}

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];
const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];

beforeEach(() => {
  logLines.length = 0;
  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    void logLines.push({level, category, message, fields});
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
});

afterEach(async () => {
  await stopOwnedEngines(clients, servers);
  setLogger();
});

const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: userId}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  let connected: Frame = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type !== 'connected') {
        if (frame.type === 'pong') resolve();
        else frames.push(frame);
        return;
      }

      connected = frame;
      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    });
  });
  return {connected, frames};
};

describe('listing conversations over the WebSocket protocol', () => {
  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    const inner = new InMemorySessionStore();
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: (userId, options) => {
        seen.push({userId, options});
        return summaries;
      },
    };
    const url = await startEngine(store, 'u1');
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect({seen, frames}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      frames: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
    const inner = new InMemorySessionStore();
    const withoutList = await startEngine(delegatingTo(inner));
    const failingList = await startEngine({
      ...delegatingTo(inner),
      listFor: () => Promise.reject(new Error('database offline')),
    });

    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});

    expect({
      unimplemented: unimplemented.frames,
      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR'}],
      logged: [
        {
          level: 'error',
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
        },
      ],
    });
  });

  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
    const inner = new InMemorySessionStore();
    let calls = 0;
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: () => {
        calls += 1;
        return [];
      },
    };
    const url = await startEngine(store);
    const badFrames = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    const codes: Array<string | undefined> = [];
    for (const bad of badFrames) {
      const {frames} = await askAfterConnect(url, bad);
      codes.push(frames[0]?.code);
    }
    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});

    expect({codes, accepted, calls}).toEqual({
      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
      accepted: [{type: 'session_list', sessions: []}],
      calls: 1,
    });
  });
});
specs/hal-engine-websocket-protocol/spec.md:71:- An upgrade whose `Host` header is missing or empty (RFC 6455 §4.1 requires one), or whose request-target is not a URL, such as `//`, is answered with HTTP 400 ([validated by: answers an empty Host, a missing Host and a // target with 400 instead of throwing out of the upgrade listener](../../src/transport/malformedUpgrade.test.ts#L68)).
specs/hal-engine-websocket-protocol/spec.md:72:- The path check reads the target alone and never throws: a path beginning with `{basePath}/ws` passes, as §2.1 says; any other path, an empty target or `//` fails ([validated by: accepts any path beginning with /hal/ws and refuses another path, an empty target and //, without throwing](../../src/transport/ws/wsPath.test.ts#L4)).
specs/hal-engine-websocket-protocol/spec.md:73:- A `WsAuthenticator` that throws synchronously, rather than returning a rejected promise, is answered with HTTP 500, as a rejection is ([validated by: answers 500 when the authenticator throws synchronously instead of rejecting](../../src/transport/malformedUpgrade.test.ts#L82)).
specs/hal-engine-websocket-protocol/spec.md:74:- A `WsAuthenticator` that throws or rejects is logged at `error` as `authenticator failed` with its error's type alone, never its message, which can carry the credential it was checking ([validated by: logs a throwing or rejecting authenticator by its error type alone, never its message](../../src/transport/malformedUpgrade.test.ts#L92)).
specs/hal-engine-websocket-protocol/spec.md:75:- A `WsAuthenticator` that returns a user directly, not in a promise, is treated like one that resolves to it, rather than failing inside the listener ([validated by: upgrades a request whose authenticator returns a user without a promise](../../src/transport/malformedUpgrade.test.ts#L118)).
specs/hal-engine-websocket-protocol/spec.md:76:- A well-formed upgrade is unaffected ([validated by: still upgrades a well-formed request](../../src/transport/malformedUpgrade.test.ts#L126)).
specs/hal-engine-websocket-protocol/spec.md:130:Any other field is ignored, and the validator forwards only the fields the frame defines. In particular the server does not read a `chatId` from this message: the connection already determines the session ([validated by: drops any field the frame does not define, rather than forwarding it](../../src/transport/ws/validation.test.ts#L18)).
specs/hal-engine-websocket-protocol/spec.md:140:- A session processes one `user_message` at a time, in the order the frames arrived: a frame arriving while an earlier one is still running waits, and its answer starts only after the earlier run's `stream_end` ([validated by: answers a second user_message only after the first has sent its stream_end, in the order they arrived](../../src/transport/ws/messageHandler.test.ts#L666)).
specs/hal-engine-websocket-protocol/spec.md:141:- The waiting message's model request therefore holds the earlier answer finished, never one still streaming ([validated by: hands the second run a history whose first answer is finished, never one still streaming](../../src/transport/ws/messageHandler.test.ts#L697)).
specs/hal-engine-websocket-protocol/spec.md:142:- A `ping` is answered at once, even while a run is pending ([validated by: answers a ping at once while a run is pending](../../src/transport/ws/messageHandler.test.ts#L715)).
specs/hal-engine-websocket-protocol/spec.md:143:- A frame that fails validation and is not a `user_message`, such as a malformed `ping`, gets its `INVALID_MESSAGE` at once, even while a run is pending, but a `user_message` that fails validation is answered in turn, its `INVALID_MESSAGE` and `stream_end` after the run in progress, since an `error` frame names no message and would otherwise read as the running answer's ([validated by: answers an invalid ping at once but an invalid user_message in turn, after the run in progress](../../src/transport/ws/messageHandler.test.ts#L728)).
specs/hal-engine-websocket-protocol/spec.md:144:- The reconnect flush (§ 11.3), which sends queued messages in one burst, is therefore safe: they are answered one after another, in the order the user typed them ([validated by: queues three messages sent in one tick before the handler returns, and answers them in that order](../../src/transport/ws/messageHandler.test.ts#L744)).
specs/hal-engine-websocket-protocol/spec.md:145:- A queued message whose socket has closed by the time its turn comes is dropped, neither recorded nor answered, since nobody is left to read the answer and a session whose last socket closed has no credentials left ([validated by: drops a queued message whose socket closed before its turn, without asking the model or recording it](../../src/transport/ws/messageHandler.test.ts#L761)).
specs/hal-engine-websocket-protocol/spec.md:165:Requests summaries of the conversations belonging to the authenticated user on this connection. The server MUST take the user id from the authenticated session and MUST ignore any `userId` supplied in the frame. The request returns a `session_list` without starting a message stream ([validated by: reads list_sessions from the injected session store for the connected user](../../src/transport/ws/messageHandler.test.ts#L72)).
specs/hal-engine-websocket-protocol/spec.md:186:The server MUST reject malformed paging fields with `INVALID_MESSAGE`. It MUST pass the paging values to `SessionStore.listFor` as supplied and return `session_list` with the resulting summaries; each summary contains only its `sessionId`, `createdAt`, `updatedAt`, and `entryCount`, with both dates serialized as ISO-8601 strings ([validated by: answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId](../../src/transport/conversationList.acceptance.test.ts#L75)).
specs/hal-engine-websocket-protocol/spec.md:280:Notifies the client that a session entry was created on the server and will never be sent. This happens under output suppression (see [tool-responses.md](../hal-engine-tool-responses/spec.md)): the server keeps the entry so the model retains context, and the client does not need it for display ([validated by: still records a suppressed reply in the session, so history keeps it](../../src/transport/ws/messageHandler.test.ts#L231)).
specs/hal-engine-websocket-protocol/spec.md:296:- An entry **opened while suppression is already active** is announced with `entry_skip` and nothing else: no `entry_upsert`, no `entry_delta`, no `entry_commit` follows it ([validated by: skips rather than upserts a segment opened after suppression](../../src/transport/ws/messageHandler.test.ts#L223)).
specs/hal-engine-websocket-protocol/spec.md:297:- An entry **already sent before suppression began** cannot be skipped, because the client is displaying it. The server retracts it instead, by re-sending `entry_upsert` at the same index with the entry's `content` set to `""`. The client renders an empty assistant entry as nothing, so the text disappears ([validated by: blanks an assistant entry that was already sent](../../src/transport/ws/messageHandler.test.ts#L200)).
specs/hal-engine-websocket-protocol/spec.md:298:- An entry **still streaming when suppression begins** is first committed as streamed so far, with `entry_commit`, and is from then on an entry already sent: an answer is retracted as above, a thought stays as the client saw it, and whatever the model writes next opens a new entry announced with `entry_skip` ([validated by: commits and retracts an answer still open when suppression begins, and skips what follows as a new entry](../../src/transport/ws/messageHandler.test.ts#L287), [validated by: commits a thought still open when suppression begins as the client saw it, and skips what follows](../../src/transport/ws/messageHandler.test.ts#L308)).
specs/hal-engine-websocket-protocol/spec.md:302:- Only assistant entries are ever retracted; a thinking entry is never blanked, even when it was sent before suppression began ([validated by: never blanks a thinking entry, only assistant ones](../../src/transport/ws/messageHandler.test.ts#L215)).
specs/hal-engine-websocket-protocol/spec.md:303:- Each sent entry is blanked once, so a second suppression in the same stream repeats nothing ([validated by: blanks each sent entry once, so a second suppression repeats nothing](../../src/transport/ws/messageHandler.test.ts#L249)).
specs/hal-engine-websocket-protocol/spec.md:304:- An entry the client only ever saw as `entry_skip` is never retracted, because nothing is displayed to retract ([validated by: does not resurrect an entry the client only ever saw skipped](../../src/transport/ws/messageHandler.test.ts#L241)).
specs/hal-engine-websocket-protocol/spec.md:343:- A message the server cannot parse into a known type is answered with `INVALID_MESSAGE`, and no message stream is started for it ([validated by: rejects an unparseable message and never starts a stream](../../src/transport/ws/messageHandler.test.ts#L91)).
specs/hal-engine-websocket-protocol/spec.md:344:- A rate limit reported by the AI provider is surfaced as `RATE_LIMITED`, which tells the client the same request is worth retrying ([validated by: tells the client to retry when the provider is rate limited](../../src/transport/ws/messageHandler.test.ts#L331)).
specs/hal-engine-websocket-protocol/spec.md:345:- Any other failure raised while processing a message is reported as `SERVER_ERROR` ([validated by: reports any other failure as a server error](../../src/transport/ws/messageHandler.test.ts#L340)).
specs/hal-engine-websocket-protocol/spec.md:349:Response to a client `ping`. The server MUST echo the client's timestamp without modification ([validated by: answers a ping with the timestamp it was given](../../src/transport/ws/messageHandler.test.ts#L101)).
specs/hal-engine-websocket-protocol/spec.md:363:The server answers a ping even if the connection's turn signal has been aborted ([validated by: answers a ping whose connection signal is aborted](../../src/transport/ws/messageHandler.test.ts#L829)).
specs/hal-engine-websocket-protocol/spec.md:367:The response to `list_sessions`. The server sends it only in response to a request; it does not push conversation lists unsolicited. Each row describes one conversation belonging to the authenticated user and carries metadata only, with no conversation entries or credentials ([validated by: answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId](../../src/transport/conversationList.acceptance.test.ts#L75)).
specs/hal-engine-websocket-protocol/spec.md:392:A list request is not a turn: it is answered while another message is streaming, without waiting for that session's turn lock ([validated by: answers a ping at once while a run is pending](../../src/transport/ws/messageHandler.test.ts#L715)). A session store without `listFor` answers an empty list; a failing store answers `SERVER_ERROR` and logs the failure ([validated by: answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws](../../src/transport/conversationList.acceptance.test.ts#L116)).
specs/hal-engine-websocket-protocol/spec.md:412:- If the tool budget is exhausted without a hook sentence, the synthetic stop emits no extra frame and the run still ends with `stream_end` ([validated by: sends no frame for the synthetic stop when no hook wrote a sentence, so the run ends as it did without one](../../src/transport/ws/messageHandler.test.ts#L617)).
specs/hal-engine-websocket-protocol/spec.md:521:3. The server sends `entry_commit`. The client MUST set `isStreaming` to `false`, matching the committed entry the server keeps in the session. No further deltas will arrive for this entry ([validated by: leaves the committed assistant entry in the session, no longer streaming](../../src/transport/ws/messageHandler.test.ts#L125)).
specs/hal-engine-websocket-protocol/spec.md:522:4. Every entry the server opens is committed by the time the turn ends, on every terminal path: a `stop`, a round that ends without one, and a provider that throws mid-stream. The partial content is committed exactly as streamed, and on a throw the `entry_commit` frames arrive before the `error` frame ([validated by: commits a partial answer as streamed, before the error, when the provider throws](../../src/transport/ws/messageHandler.test.ts#L434), [validated by: commits the answer, flagged truncated, when a round ends on a tool call with no stop chunk](../../src/transport/ws/messageHandler.test.ts#L469)).
specs/hal-engine-websocket-protocol/spec.md:523:5. An entry committed because the run ended before it finished (a provider failure, or a round with no `stop`) carries `truncated: true`, in the session and on the wire: the server re-sends it as an `entry_upsert` with the flag just before its `entry_commit`, so a live client and a replay of the stored entry both see it, and a client can render a cut-off answer as cut off without the transient `error` frame. An entry committed on a `stop` never carries the field, and a suppressed entry is flagged in the session but never re-sent. Any text the thinking-tag parser still held is flushed into the entry first, as a `stop` does ([validated by: flags a partial answer truncated in the session and re-sends it with the flag before its commit](../../src/transport/ws/messageHandler.test.ts#L508), [validated by: leaves an entry committed on a stop chunk without the flag and sends it once](../../src/transport/ws/messageHandler.test.ts#L536), [validated by: flags a suppressed entry that a throw cut short in the session but never re-sends it](../../src/transport/ws/messageHandler.test.ts#L548), [validated by: keeps the text the thinking-tag parser still held when a throw cuts the answer short](../../src/transport/ws/messageHandler.test.ts#L560)).
specs/hal-engine-websocket-protocol/spec.md:534:The entry is fully formed in the `entry_upsert` message, so a tool call yields one `entry_upsert` and nothing further. The client MUST NOT expect `entry_delta` or `entry_commit` for these entries ([validated by: sends a tool entry for a tool call](../../src/transport/ws/messageHandler.test.ts#L181)).
specs/hal-engine-websocket-protocol/spec.md:549:- A reply with no tool calls and no thinking produces, in order, the user entry, the assistant entry opened empty, one `entry_delta` per text chunk, its `entry_commit`, and `stream_end` ([validated by: sends the user entry, then the assistant entry, its delta, its commit and stream_end](../../src/transport/ws/messageHandler.test.ts#L111)).
specs/hal-engine-websocket-protocol/spec.md:550:- A thinking block is committed before the assistant entry that follows it is opened, so the two never interleave ([validated by: commits the thinking entry before the assistant entry opens](../../src/transport/ws/messageHandler.test.ts#L137)).
specs/hal-engine-websocket-protocol/spec.md:573:**Commit frames are not emitted in index order.** Above, `entry_commit` for index 1 arrives after `entry_upsert` for index 2. A thinking entry is committed when the next text segment arrives, not when a tool entry appears, so a tool call between thinking and the answer lands in the gap. A client that assumes commits arrive in ascending index order, or that an entry is committed before the next one opens, will mis-render this exchange ([validated by: commits the thinking entry when text resumes, not when a tool entry appears](../../src/transport/ws/messageHandler.test.ts#L154)).
specs/hal-engine-websocket-protocol/spec.md:621:The second `entry_upsert` at index 1 is the retraction: same index, empty content. Index 1 is NOT tracked as skipped -- it still occupies its slot in the client array. Index 4, the model's suppressed follow-up, is ([validated by: writes the sentence into the session but only skips it on the wire under suppression](../../src/transport/ws/messageHandler.test.ts#L603)).
specs/hal-engine-websocket-protocol/spec.md:641:When the AI model requests a tool invocation, the server executes the tool and re-queries the model with the result. The loop is bounded by `maxToolRounds` (default 5): at most `maxToolRounds` tool rounds are executed, and the provider is called at most `maxToolRounds + 1` times, so the default permits six model calls: the first, plus five more that each read a round's tool results. A tool round the model requests once the budget is spent is not executed; the turn ends on that call's output. No new frame type is introduced for this outcome: a consumer's `onToolBudgetExhausted` sentence arrives as an ordinary assistant entry (`entry_upsert`, `entry_delta`, `entry_commit`), and the turn still ends with `stream_end`, never `error` ([validated by: renders the hook's sentence as its own committed entry, then stream_end, with no error](../../src/transport/ws/messageHandler.test.ts#L591)).
specs/hal-engine-websocket-protocol/spec.md:643:An invented tool name and a tool executor failure likewise complete the turn without an error frame ([validated by: completes a turn whose tool name the model invented: its answer streams, then stream_end, with no error frame](../../src/transport/ws/messageHandler.test.ts#L839), [validated by: completes a turn whose tool executor threw: its answer streams, then stream_end, with no error frame](../../src/transport/ws/messageHandler.test.ts#L845)).
specs/hal-engine-websocket-protocol/spec.md:661:Messages a tool addresses to the client are forwarded verbatim, in the position the stream produced them, rather than being rewritten into entries of the server's own ([validated by: forwards a tool result to the client untouched](../../src/transport/ws/messageHandler.test.ts#L189)).
specs/hal-engine-websocket-protocol/spec.md:679:The client SHOULD close the WebSocket with code 1000 (Normal Closure). The server keeps the session: it erases nothing on close, and the credentials the socket carried are cleared from it. Closing the socket abandons the turn it started: the run stops, no `stream_end` follows, and the session keeps the answer as it stood, committed and flagged `truncated` ([abandon-on-close](../hal-engine-abandon-on-close/spec.md)). A turn whose connection signal was already aborted is dropped without recording, asking the model, or sending frames ([validated by: drops a turn whose connection signal is already aborted: records nothing, asks nothing, sends nothing](../../src/transport/ws/messageHandler.test.ts#L796)).
specs/hal-engine-websocket-protocol/spec.md:694:- An entry still streaming when its conversation is resumed is replayed with `isStreaming: false` and `truncated: true`: the rest of its turn streams to the connection that started it, so this one would wait for a commit that never comes ([validated by: replays an entry whose turn is still running as finished and truncated, leaving the stored entry as it is](../../src/transport/sessionResume.test.ts#L346)).
specs/hal-engine-websocket-protocol/spec.md:695:- With the server's `latest` option, a client that has lost the id, after a page refresh for instance, MAY connect without one and still rejoin its user's most recent conversation, and sends `?new=1` to start a new conversation instead ([validated by: with latest on, rejoins the most recently active session of a user whose connect names none](../../src/transport/sessionResume.test.ts#L410), [validated by: with latest on, starts a new session for a user with none, and on ?new=1 even when one exists](../../src/transport/sessionResume.test.ts#L427)).
specs/hal-engine-conversation-list/spec.md:12:- A summary is `sessionId`, `createdAt`, `updatedAt` and `entryCount`, and nothing else: neither the conversation's entries nor its credentials, so a list can never hand over either, even for a session created with credentials ([validated by: carries only its four fields, so a list can never hand over a conversation or a credential](../../src/infrastructure/stores/sessionStoreListSignature.test.ts#L22)).
specs/hal-engine-conversation-list/spec.md:13:- `listFor` is optional, like `latestFor` and `lookup` before it: a store written against the five original members still satisfies the interface, and both shipped stores implement it ([validated by: leaves a store with only the five original members satisfying the interface beside both shipped ones](../../src/infrastructure/stores/sessionStoreListSignature.test.ts#L11)).
specs/hal-engine-conversation-list/spec.md:17:- Summaries come back most recent activity first ([validated by: answers newest activity first, headed by the very session latestFor returns](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L27)).
specs/hal-engine-conversation-list/spec.md:18:- The first summary is the session `latestFor` returns, because both read the same activity ([validated by: answers newest activity first, headed by the very session latestFor returns](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L27)).
specs/hal-engine-conversation-list/spec.md:19:- The order is total rather than merely sorted: two conversations last active in the same millisecond are ordered by session id, the larger first, which is what lets a page resume without dropping one of them ([validated by: keeps a conversation tied on activity rather than dropping it across a page boundary](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L141)).
specs/hal-engine-conversation-list/spec.md:20:- In `InMemorySessionStore` that tie-break is the list's alone: `latestFor` breaks the same tie by creation order, so for two tied conversations the head of the list and the session a resume rejoins can differ ([validated by: breaks a tie on activity by session id, where latestFor takes the session created later](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L42)).
specs/hal-engine-conversation-list/spec.md:21:- `MongoSessionStore` answers in order of `updatedAt`, which each `save` moves forward, and its first summary is the session its own `latestFor` returns ([validated by: answers the user's conversations newest saved first, headed by the one latestFor returns](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L31)).
